// توليد كل المجموعات الجزئية باستخدام التراجع
function subsets(nums: number[]): number[][] {
    const result: number[][] = [];

    function backtrack(start: number, current: number[]) {
        result.push([...current]); // أضف نسخة من المجموعة الحالية
        for (let i = start; i < nums.length; i++) {
            current.push(nums[i]);
            backtrack(i + 1, current);
            current.pop(); // تراجع: أزل آخر عنصر
        }
    }

    backtrack(0, []);
    return result;
}

