// فرز إدراج لمصفوفة نصوص أبجدياً
function insertionSort(arr: string[]): string[] {
    for (let i = 1; i < arr.length; i++) {
        const key = arr[i];
        let j = i - 1;
        // انقل العناصر الأكبر من المفتاح إلى اليمين
        while (j >= 0 && arr[j].localeCompare(key) > 0) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = key;
    }
    return arr;
}

