function generatePascal(numRows: number): number[][] {
  const triangle: number[][] = [];
  for (let i = 0; i < numRows; i++) {
    // كل صف يبدأ وينتهي بـ 1
    const row: number[] = [1];
    for (let j = 1; j < i; j++) {
      // القيمة الوسطى هي مجموع القيمتين فوقها
      row.push(triangle[i-1][j-1] + triangle[i-1][j]);
    }
    if (i > 0) row.push(1);
    triangle.push(row);
  }
  return triangle;
}

