class CircularQueue {
  private data: number[];
  private front = 0;
  private rear = 0;
  private size = 0;
  private capacity: number;

  constructor(capacity: number) {
    this.capacity = capacity;
    this.data = new Array(capacity);
  }

  enqueue(item: number): boolean {
    if (this.size === this.capacity) return false; // ممتلئ
    this.data[this.rear] = item;
    this.rear = (this.rear + 1) % this.capacity; // التفاف
    this.size++;
    return true;
  }

  dequeue(): number | undefined {
    if (this.size === 0) return undefined; // فارغ
    const item = this.data[this.front];
    this.front = (this.front + 1) % this.capacity;
    this.size--;
    return item;
  }
}

