class Stack<T> {
  private items: T[] = [];

  // ندفع عنصراً إلى أعلى المكدّس
  push(item: T): void {
    this.items.push(item);
  }

  // نزيل العنصر العلوي ونعيده، أو undefined إذا كان المكدّس فارغاً
  pop(): T | undefined {
    return this.items.pop();
  }

  // نطّلع على العنصر العلوي دون إزالته
  peek(): T | undefined {
    return this.items[this.items.length - 1];
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }
}

const stack = new Stack<number>();
stack.push(10);
stack.push(20);
stack.push(30);
console.log(stack.peek()); // القمة 30
console.log(stack.pop());  // نزيل 30
console.log(stack.pop());  // نزيل 20
console.log(stack.isEmpty()); // لم يتبقَّ سوى 10

